def find_unselected_required(ctx, nb):
    clickables = ctx.state.clickables
    task = ctx.task
    required_color = task.required_color
    required_size = task.required_size
    required_material = task.required_material
    if required_color:
        for c in clickables:
            if required_color.lower() in c.lower():
                return c
    if required_size:
        for c in clickables:
            if required_size.lower() in c.lower():
                return c
    if required_material:
        for c in clickables:
            if required_material.lower() in c.lower():
                return c
    return None

def hook(ctx, nb):
    action = ctx.action
    if not action:
        return None
    action_val = action.value_normalized
    if action_val != "buy now" and "buy now" not in action_val:
        return None
    unselected = find_unselected_required(ctx, nb)
    if unselected:
        return {"kind": "rewrite_action", "action": "click[" + unselected + "]", "message": "Select required attribute " + unselected + " before buying"}
    return None
